import React, { useState, useRef, useEffect } from 'react';
import './VideoCarousel.css';

const VideoCarousel = ({ language }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const videoRefs = useRef([]); 
  const sectionRef = useRef(null);

  // Анимация при скролле
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const videos = [
    { id: 1, src: "/videos/tyumen_edit_1.mp4" },
    { id: 2, src: "/videos/tyumen_edit_2.mp4" },
    { id: 3, src: "/videos/tyumen_edit_3.mp4" }
  ];

  const pauseAllVideos = () => {
    videoRefs.current.forEach((video) => {
      if (video && !video.paused) {
        video.pause();
      }
    });
  };

  const handlePlay = (index) => {
    videoRefs.current.forEach((video, i) => {
      if (i !== index && video && !video.paused) {
        video.pause();
      }
    });
  };

  const nextVideo = () => {
    pauseAllVideos(); 
    setCurrentIndex((prev) => (prev + 1) % videos.length);
  };

  const prevVideo = () => {
    pauseAllVideos(); 
    setCurrentIndex((prev) => (prev - 1 + videos.length) % videos.length);
  };

  const publicUrl = process.env.PUBLIC_URL || '';

  return (
    <section 
      className={`video-section ${isVisible ? 'animate-in' : ''}`} 
      id="videos" 
      ref={sectionRef}
    >
      <div className="container">
        <h2 className="section-title" style={{ transition: 'opacity 0.8s ease, transform 0.8s ease', opacity: isVisible ? 1 : 0, transform: isVisible ? 'translateY(0)' : 'translateY(30px)' }}>
          {language === 'RU' ? 'Тюмень в движении' : 'Tyumen in Motion'}
        </h2>
        
        <div className="carousel-container" style={{ transition: 'opacity 0.8s ease 0.2s, transform 0.8s ease 0.2s', opacity: isVisible ? 1 : 0, transform: isVisible ? 'translateY(0)' : 'translateY(30px)' }}>
          
          {/* ПРОЗРАЧНЫЕ ЗОНЫ КЛИКА ДЛЯ БОКОВЫХ ВИДЕО */}
          <div className="carousel-click-zone left" onClick={prevVideo}></div>
          <div className="carousel-click-zone right" onClick={nextVideo}></div>

          <button className="carousel-btn prev" onClick={prevVideo}>&#8249;</button>

          <div className="carousel-content">
            {videos.map((video, index) => {
              let positionClass = 'hidden';
              if (index === currentIndex) positionClass = 'active';
              else if (index === (currentIndex - 1 + videos.length) % videos.length) positionClass = 'prev';
              else if (index === (currentIndex + 1) % videos.length) positionClass = 'next';

              return (
                <div key={video.id} className={`video-wrapper ${positionClass}`}>
                  <video 
                    ref={(el) => (videoRefs.current[index] = el)} 
                    onPlay={() => handlePlay(index)} 
                    controls={index === currentIndex} 
                    poster={`${publicUrl}/images/bg-${index + 1}.jpg`} 
                    className="carousel-video"
                    loading="lazy"
                  >
                    <source src={`${publicUrl}${video.src}`} type="video/mp4" />
                  </video>
                </div>
              );
            })}
          </div>

          <button className="carousel-btn next" onClick={nextVideo}>&#8250;</button>
        </div>
        
        <div className="carousel-dots" style={{ transition: 'opacity 0.8s ease 0.4s', opacity: isVisible ? 1 : 0 }}>
          {videos.map((_, index) => (
            <span 
              key={index} 
              className={`dot ${index === currentIndex ? 'active' : ''}`}
              onClick={() => {
                pauseAllVideos();
                setCurrentIndex(index);
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

export default VideoCarousel;